import { useState } from "react";
import ListaDeTarefas from "./components/ListaDeTarefas";
import "./App.css";

const TAREFAS_EXEMPLO = [
  "Estudar renderização condicional",
  "Fazer a atividade prática",
  "Revisar o operador ternário",
];

function App() {
  const [tarefas, setTarefas] = useState(TAREFAS_EXEMPLO);

  function alternarTarefas() {
    setTarefas((atual) => (atual.length > 0 ? [] : TAREFAS_EXEMPLO));
  }

  return (
    <div className="App">
      <ListaDeTarefas tarefas={tarefas} />

      <button className="app-botao" onClick={alternarTarefas}>
        {tarefas.length > 0 ? "Esvaziar lista" : "Repopular lista"}
      </button>
    </div>
  );
}

export default App;
